using System;
using System.IO;
using System.Linq;
using NetworkHub.App;
using NetworkHub.Dns;
namespace NetworkHub.Desktop;
internal static class TestsDnsReapply
{
    static void Check(bool condition,string detail){if(!condition)throw new Exception(detail);}
    static void Reject(Action operation){try{operation();}catch(Exception ex)when(ex is DnsException or IOException or InvalidDataException){return;}throw new Exception("Unsafe repeat accepted");}
    internal static void Run(Action<string,Action> test,AppFiles files)
    {
        test("DNS disabled DoH: empty native properties match zero flags without losing backup data",()=>{
            var plain=TestsDns.Fixture().State;var disabled=plain with{IPv4=plain.IPv4 with{Encryption=plain.IPv4.Servers.Select(s=>new DnsDohSettings(s,null,0)).ToArray()}};
            Check(plain.SameConfiguration(disabled)&&plain.Fingerprint()==disabled.Fingerprint()&&disabled.IPv4.Encryption.Length==plain.IPv4.Servers.Length,"Disabled native omission disagrees or backup lost");
            foreach(var property in new[]{new DnsDohSettings(plain.IPv4.Servers[0],"https://dns.example/query",0),new DnsDohSettings(plain.IPv4.Servers[0],"https://dns.example/query",2),new DnsDohSettings(plain.IPv4.Servers[0],null,1)})Check(!plain.SameConfiguration(plain with{IPv4=plain.IPv4 with{Encryption=new[]{property}}}),"Meaningful DoH mismatch ignored");
        });
        test("DNS interrupted disable DoH: repeat verifies persisted destination and keeps original",()=>{
            var fake=TestsDns.Fixture();var original=fake.State;var comss=DnsProfiles.All[0];var encrypted=original with{IPv4=DnsProfiles.ProfilePlan(original.IPv4,comss.IPv4,comss,true,false)};var disabled=encrypted with{IPv4=DnsProfiles.ProfilePlan(encrypted.IPv4,comss.IPv4,comss,false,false)};fake.State=disabled;
            var store=new TestsDns.FakeStore{Journal=new DnsJournal(1,Guid.NewGuid(),"test",original,encrypted,disabled,new[]{DnsFamily.IPv4},DnsPhase.Writing,DnsFamily.IPv4,DateTime.UtcNow.ToString("O"),""){RollbackTarget=encrypted,Action="apply",ProfileId="comss",ProfileName="ComssDNS"}};var id=store.Journal.Id;
            Check(DnsTransaction.CanCompletePendingWrite(store.Journal,disabled),"Completed intent not recognized");new DnsTransaction(fake,fake,store,"test").Reapply(disabled,disabled,new[]{DnsFamily.IPv4},"comss");
            Check(fake.Writes==1&&store.Journal!.Id==id&&store.Journal.Before.SameConfiguration(original)&&store.Journal.Phase==DnsPhase.Applied&&store.Journal.History.Length==2,"Repeat lost original or intent history");
            new DnsTransaction(fake,fake,store,"test").Restore(original.AdapterId,fake.State.Fingerprint());Check(fake.State.SameConfiguration(original),"Original restoration failed");
        });
        test("DNS interrupted repeat: partial foreign owner and unsupported states remain blocked",()=>{
            var fake=TestsDns.Fixture();var original=fake.State;var target=original with{IPv4=new(DnsMode.Manual,DnsProfiles.All[0].IPv4,DnsProfiles.All[0].IPv4)};fake.State=target;
            var baseline=new DnsJournal(1,Guid.NewGuid(),"test",original,original,target,new[]{DnsFamily.IPv4},DnsPhase.Writing,DnsFamily.IPv4,DateTime.UtcNow.ToString("O"),"");
            foreach(var invalid in new[]{baseline with{Owner="foreign"},baseline with{Pending=null},baseline with{Phase=DnsPhase.Restoring},baseline with{Phase=DnsPhase.RollingBack},baseline with{Target=target with{IPv6=new(DnsMode.Manual,new[]{"2606:4700:4700::1111"},Array.Empty<string>())}}}){var store=new TestsDns.FakeStore{Journal=invalid};Reject(()=>new DnsTransaction(fake,fake,store,"test").Reapply(target,target,new[]{DnsFamily.IPv4},"comss"));Check(fake.Writes==0&&store.Saves==0,"Unverified intent adopted");}
            Check(!DnsTransaction.CanCompletePendingWrite(baseline,target with{CanChange=false})&&!DnsTransaction.CanCompletePendingWrite(baseline,target with{DependencyFingerprint="foreign"}),"Inspection/identity check bypassed");
        });
        test("DNS repeat: five scoped write requests retain encrypted Xbox original across restart",()=>{
            string path=Path.Combine(files.Data,"Repeat-restart",Guid.NewGuid().ToString("N"));var fake=TestsDns.Fixture(path);var xbox=DnsProfiles.All[1];fake.State=fake.State with{IPv4=DnsProfiles.ProfilePlan(fake.State.IPv4,xbox.IPv4,xbox,true,false)};var original=fake.State;var store=new DnsFileJournalStore(path,"test");var tx=new DnsTransaction(fake,fake,store,"test");var comss=DnsProfiles.All[0];var target=fake.State with{IPv4=DnsProfiles.ProfilePlan(fake.State.IPv4,comss.IPv4,comss,true,false)};tx.Apply(fake.State,target,new[]{DnsFamily.IPv4},"comss",true);var id=store.Load(original.AdapterId)!.Id;
            for(int i=0;i<5;i++){var proof=new DnsOperationEvidence();new DnsTransaction(fake,fake,store,"test",proof).Reapply(fake.State,fake.State,new[]{DnsFamily.IPv4},"comss");Check(proof.AcceptedWrites==1&&proof.VerifiedWrites==1&&proof.ValuesChanged==false&&!proof.NetworkStateChangeConfirmed&&proof.CacheResult=="not performed"&&proof.HttpsResult=="not tested","Repeat was skipped or evidence claimed network repair");}
            var record=store.Load(original.AdapterId)!;Check(fake.Writes==6&&record.Id==id&&record.Before.SameConfiguration(original)&&record.History.Count(h=>h.Action=="reapply")==5,"Original replaced");var restart=TestsDns.Fixture(path);new DnsTransaction(restart,restart,new DnsFileJournalStore(path,"test"),"test").Restore(original.AdapterId,restart.State.Fingerprint());Check(restart.State.SameConfiguration(original),"Offline restart recovery lost Xbox DoH");
        });
        test("DNS repeat: external plain profile gets its own current baseline",()=>{var fake=TestsDns.Fixture();fake.State=fake.State with{IPv4=new(DnsMode.Manual,DnsProfiles.All[0].IPv4,DnsProfiles.All[0].IPv4)};var original=fake.State;var store=new TestsDns.FakeStore();var tx=new DnsTransaction(fake,fake,store,"test");tx.Reapply(original,original,new[]{DnsFamily.IPv4},"comss");Check(fake.Writes==1&&store.Journal!.Before.SameConfiguration(original)&&fake.State.IPv4.Encryption.Length==0,"Repeat encrypted or replaced external original");tx.Restore(original.AdapterId,fake.State.Fingerprint());Check(fake.State.SameConfiguration(original),"External original lost");});
        test("DNS repeat: profile DNS DoH order adapter and capability mismatch blocked",()=>{var before=TestsDns.Fixture().State;foreach(var target in new[]{before with{IPv4=new(DnsMode.Manual,DnsProfiles.All[0].IPv4,DnsProfiles.All[0].IPv4)},before with{AdapterId=Guid.NewGuid()},before with{IPv4=before.IPv4 with{Servers=before.IPv4.Servers.Reverse().ToArray()}},before with{IPv4=before.IPv4 with{Encryption=before.IPv4.Servers.Select(ip=>new DnsDohSettings(ip,"https://dns.example/query",2)).ToArray()}}})Reject(()=>DnsTransaction.ValidateReapply(before,target,new[]{DnsFamily.IPv4}));Reject(()=>DnsTransaction.ValidateReapply(before with{CanChange=false},before,new[]{DnsFamily.IPv4}));var auto=before with{IPv4=new(DnsMode.Automatic,Array.Empty<string>(),Array.Empty<string>())};Reject(()=>DnsTransaction.ValidateReapply(auto,auto,new[]{DnsFamily.IPv4}));});
        test("DNS repeat: mixed encrypted flags remain exact without security downgrade",()=>{var fake=TestsDns.Fixture();fake.State=fake.State with{IPv4=fake.State.IPv4 with{Encryption=fake.State.IPv4.Servers.Select((ip,index)=>new DnsDohSettings(ip,"https://dns.example/query",index==0?2UL:6UL)).ToArray()}};var before=fake.State;new DnsTransaction(fake,fake,new TestsDns.FakeStore(),"test").Reapply(before,before,new[]{DnsFamily.IPv4},"custom");Check(fake.State.SameConfiguration(before),"Mixed policy changed");});
        test("DNS repeat: backup failure and foreign changes prevent writes",()=>{var fake=TestsDns.Fixture();var before=fake.State;var store=new TestsDns.FakeStore{FailOn=1};Reject(()=>new DnsTransaction(fake,fake,store,"test").Reapply(before,before,new[]{DnsFamily.IPv4},"custom"));Check(fake.Writes==0,"Write without backup");store.FailOn=0;var tx=new DnsTransaction(fake,fake,store,"test");tx.Reapply(before,before,new[]{DnsFamily.IPv4},"custom");fake.State=before with{DependencyFingerprint="external-policy"};Reject(()=>tx.Reapply(fake.State,fake.State,new[]{DnsFamily.IPv4},"custom"));Check(fake.Writes==1,"Foreign state overwritten");});
        test("DNS repeat: write error and verification error have independent evidence",()=>{foreach(bool verify in new[]{false,true}){var fake=TestsDns.Fixture();var original=fake.State;var proof=new DnsOperationEvidence();bool once=false;if(verify)fake.AfterWrite=()=>{if(!once){once=true;fake.ReadOverride=value=>{fake.ReadOverride=null;return value with{DependencyFingerprint="bad-readback"};};}};else fake.BeforeWrite=_=>throw new IOException("write rejected");Reject(()=>new DnsTransaction(fake,fake,new TestsDns.FakeStore(),"test",proof).Reapply(original,original,new[]{DnsFamily.IPv4},"custom"));Check(proof.WriteResult==(verify?"accepted":"failed")&&proof.VerificationResult==(verify?"failed":"not performed")&&proof.RecoveryResult=="verified"&&fake.State.SameConfiguration(original),"Failure evidence merged or original lost");}});
        test("DNS repeat: helper rejects cache clearing and diagnostic modes are independent",()=>{var before=TestsDns.Fixture().State;var r=new DnsRequest(Guid.NewGuid().ToString("N"),123,456,"S-1-5-21-1","en","reapply",before,before,new[]{DnsFamily.IPv4},before.Fingerprint()){ClearCache=false};Check(DnsElevated.ValidRequest(r,r.Token)&&!DnsElevated.ValidRequest(r with{ClearCache=true},r.Token),"Repeat allowed cache clearing");var probe=new TestsDns.FakeProbes();var names=probe.Run(new Uri("https://gemini.google.com/"),default,DnsProbeKind.Names).GetAwaiter().GetResult();var https=probe.Run(new Uri("https://gemini.google.com/"),default,DnsProbeKind.Https).GetAwaiter().GetResult();Check(names.NamesRequested&&!names.HttpsRequested&&names.HttpStatus==null&&!https.NamesRequested&&https.HttpsRequested&&https.HttpStatus==403,"DNS success falsely proves HTTPS/service");});
        test("DNS repeat: Google original cannot be replaced by an Xbox journal",()=>{var fake=TestsDns.Fixture();fake.State=fake.State with{IPv4=new(DnsMode.Manual,new[]{"8.8.8.8","8.8.4.4"},Array.Empty<string>())};var google=fake.State;var store=new TestsDns.FakeStore();var tx=new DnsTransaction(fake,fake,store,"test");tx.Reapply(google,google,new[]{DnsFamily.IPv4},"custom");Check(store.Journal!.Before.SameConfiguration(google),"Stale Xbox adopted");var wrong=google with{AdapterId=Guid.NewGuid()};Reject(()=>tx.Reapply(wrong,wrong,new[]{DnsFamily.IPv4},"custom"));Check(fake.Writes==1,"Wrong adapter wrote");});
    }
}
